krpano.action:
set(image.depthmap.enabled,false);
if(view.vlookat LT -80 OR view.vlookat GT +80,
	tween(view.vlookat, 0.0, 1.0, easeInOutSine);
	tween(view.fov,     100, distance(150,0.8));
  );

cm_look_straight();
tween(view.architectural, 0.0,  distance(1.0,0.5));
tween(view.pannini,       0.0,  distance(1.0,0.5));
tween(view.fisheye,       0.35, distance(1.0,0.5));

set(image.depthmap.enabled,false);
tween(view.architectural, 0.0, distance(1.0,0.5));
tween(view.pannini,       0.0, distance(1.0,0.5));
tween(view.fisheye,       1.0, distance(1.0,0.8));
tween(view.fov,           150, distance(150,0.8));
tween(view.vlookat,        90, distance(100,0.8));
add(new_hlookat, view.hlookat, 123.0);
tween(view.hlookat, get(new_hlookat), distance(100,0.8));

cm_look_straight();
tween(view.architectural, 0.0, distance(1.0,0.5));
tween(view.pannini,       0.0, distance(1.0,0.5));
tween(view.fisheye,       0.0, distance(1.0,0.5));
delayedcall(2.0,
	set(image.depthmap.enabled,true);
);


calc(local.xframes, (caller.imagewidth /framewidth) BOR 0);
calc(local.frames, xframes * ((caller.imageheight / frameheight) BOR 0));
def(local.frame, integer, 0);


calc(caller.crop, '0|0|' + framewidth + '|' + frameheight);

setinterval(calc('crop_anim_' + caller.name), calc(1.0 / framerate),
	if(caller.loaded,
		if(caller.visible,
			inc(frame);
			if(frame GE frames, if(caller.onlastframe !== null, callwith(caller, onlastframe() ) ); set(frame,0); );
			mod(xpos, frame, xframes);
			div(ypos, frame, xframes);
			Math.floor(ypos);
			mul(xpos, framewidth);
			mul(ypos, frameheight);
			calc(caller.crop, xpos + '|' + ypos + '|' + framewidth + '|' + frameheight);
		);

		,

		clearinterval(calc('crop_anim_' + caller.name));
	);
);


// 鼠标移动事件
var moveEvent = function(e) {
  window.mouse_pos(e)
}
// 浏览器兼容
var krpanoSWFObject = document.querySelector("#krpanoSWFObject");
if(krpanoSWFObject.addEventListener){
  krpanoSWFObject.addEventListener('mousemove', moveEvent, false);
} else if (krpanoSWFObject.attachEvent) {
  krpanoSWFObject.attachEvent('onmousemove', moveEvent);
}


if(measure3d_loop, stop_measuring(); );
js(sceneLoad());

set(hotspot[sky_shade].tx,get(image.ox));
set(hotspot[sky_shade].ty,calc(image.oy - 160));
set(hotspot[sky_shade].tz,get(image.oz));
set(hotspot[floor_shade].tx,get(image.ox));
set(hotspot[floor_shade].ty,calc(image.oy + 160));
set(hotspot[floor_shade].tz,get(image.oz));

js(applyLocaleHotspots());

txtadd(tooltipname, 'hot_point_', get(pointname));

addhotspot(get(tooltipname),hot_point);
hot_point.loadstyle(point_style);;

set(hot_point.tx,get(image.ox));
set(hot_point.ty,get(image.oy));
set(hot_point.tz,get(image.oz)); 

set(hot_point.ath,get(ath));
set(hot_point.atv,get(atv));  
set(hot_point.html,get(pointname));

calc(deg2rad, Math.PI / 180.0);


calc(hfov, 0.5 * hfov * deg2rad);
Math.tan(hfov);
set(caller.width, calc(hfov * 1000));
set(caller.height, 'prop');


calc(yaw, -yaw * deg2rad);
calc(pitch, pitch * deg2rad);
calc(roll, -roll * deg2rad);
Math.cos(ch, yaw);
Math.sin(sh, yaw);
Math.cos(ca, pitch);
Math.sin(sa, pitch);
Math.cos(cb, roll);
Math.sin(sb, roll);
Math.atan2(yaw,  calc(cb*sh - sb*sa*ch), calc(ca*ch));
Math.atan2(roll, calc(sb*ch - cb*sa*sh), calc(cb*ca));
Math.asin(pitch, calc(cb*sa*ch + sb*sh));
calc(caller.ath, yaw / deg2rad);
calc(caller.atv, pitch / deg2rad);
calc(caller.rotate, roll / deg2rad);
